INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 14, 'theory', 'Quiz: modern C — C11 and C23');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 0, 'How does -std=gnu11 differ from -std=c11?', '["It doesn''t", "gnu11 enables C23", "c11 allows more extensions", "gnu11 also enables GNU extensions (typeof, statement expressions and others); c11 is strictly the standard"]', 3, 'For portable code, choose -std=c11 (or c17) with -Wpedantic; GNU extensions are convenient but tie the code to gcc and clang.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 1, 'What is a flexible array member?', '["The last member of a struct — an array with no length (char data[]); the data follows the fields in one block", "A fixed-size array at the start of a struct", "An array whose size is changed by the sizeof operator", "A pointer to a dynamic array"]', 0, 'Memory is allocated as sizeof(struct) + n · sizeof(element). The struct''s sizeof does not include the tail, and struct assignment does not copy the tail.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 2, 'What does the programmer promise the compiler by declaring parameters with restrict?', '["That the pointers are not NULL", "That the function will not modify the data", "That these pointers will not be used to access the same data: the regions do not overlap", "That the pointers are aligned"]', 2, 'The promise is not checked: if the regions overlap, the result is undefined. That is why memcpy has restrict parameters and memmove does not.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 3, 'What does atomic_fetch_add(&x, 1) guarantee?', '["That the operation runs faster than a plain one", "That reading, adding and writing happen as one indivisible operation as seen by other threads", "That the variable ends up in a register", "That the order of all other operations is unchanged"]', 1, 'Atomicity removes the data race on this variable. Which other actions are visible to other threads is determined by the memory order (acquire/release/seq_cst).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 4, 'What does ckd_add(&r, a, b) from <stdckdint.h> (C23) do?', '["Adds with saturation", "Always terminates the program on overflow", "Returns the sum and puts a flag in r", "Stores the sum in r and returns true if the mathematical result does not fit in the type of r"]', 3, 'The functions ckd_add, ckd_sub and ckd_mul provide portable overflow-checked arithmetic without undefined behavior.');
